using Stardust.Core.Assets;

/// <summary>Shared recovered vertex-varying stage with independently closed pixel mask/tint choices.</summary>
internal static class TangentSpecularPreview
{
    internal static string Code(DdsColorSpace space,bool mainMask,bool tint)=>SkeletalAlbedoPreview.Header+(mainMask?"":"uniform sampler2D specular_texture : filter_linear_mipmap,repeat_enable;")+
        "uniform sampler2D normal_texture : filter_linear_mipmap,repeat_enable;uniform vec3 material_emissive=vec3(0.0);uniform vec3 light_direction_world=vec3(0.0,0.0,1.0);uniform vec3 ambient_color=vec3(0.35);uniform vec3 directional_color=vec3(0.75);uniform vec3 directional_specular=vec3(0.75);uniform vec3 vertex_specular=vec3(0.0);uniform vec3 material_specular=vec3(0.2);uniform float material_power=20.0;uniform bool bloom_enabled=false;uniform bool fade_enabled=false;uniform float fade_opacity=1.0;uniform bool visualize_alpha=false;uniform bool fixed_half_angle=false;uniform vec3 half_angle_world=vec3(0.0,0.0,1.0);varying vec3 tangent_light;varying vec3 tangent_half;"+
        CellLightingGpuPreview.Uniforms+CellLightingGpuPreview.Functions+
        "void vertex(){vec3 p=(MODEL_MATRIX*vec4(VERTEX,1.0)).xyz;vec3 n=normalize(MODEL_NORMAL_MATRIX*NORMAL);vec3 t=normalize(mat3(MODEL_MATRIX)*TANGENT);vec3 b=normalize(mat3(MODEL_MATRIX)*BINORMAL);vec3 view_delta=INV_VIEW_MATRIX[3].xyz-p;vec3 v=view_delta/max(length(view_delta),0.000001);vec3 hs=fixed_half_angle?half_angle_world:v+light_direction_world;vec3 h=hs/max(length(hs),0.000001);tangent_light=vec3(dot(light_direction_world,t),dot(light_direction_world,b),dot(light_direction_world,n));tangent_half=vec3(dot(h,t),dot(h,b),dot(h,n));cell_vertex_diffuse=ambient_color;cell_vertex_specular=vertex_specular;if(cell_lighting_enabled)cell_lighting(p,n,INV_VIEW_MATRIX[3].xyz,cell_vertex_diffuse,cell_vertex_specular);cell_vertex_diffuse+=material_emissive;}"+
        "void fragment(){vec4 main_sample=texture(albedo_texture,UV);vec4 normal_sample=texture(normal_texture,UV);vec2 xy=(normal_sample.ag-vec2(0.5))*2.0;vec3 nt=normalize(vec3(xy,sqrt(abs(1.0-dot(xy,xy)))));vec3 h=tangent_half/max(length(tangent_half),0.000001);float d=clamp(dot(tangent_light,nt),0.0,1.0);vec3 diffuse=clamp(clamp(cell_vertex_diffuse,vec3(0.0),vec3(1.0))+directional_color*d,vec3(0.0),vec3(1.0));float s=pow(clamp(dot(h,nt),0.0,1.0),material_power);vec3 raw=(s*directional_specular*material_specular+clamp(cell_vertex_specular,vec3(0.0),vec3(1.0)))*"+(mainMask?"main_sample.a":"texture(specular_texture,UV).a")+";vec3 rgb=main_sample.rgb*"+(tint?"(alpha_hue_mask?mix(first_factor,second_factor,main_sample.a):first_factor)*":"")+"diffuse+raw*(bloom_enabled?0.5:1.0);float alpha=fade_enabled?fade_opacity:dot(raw,vec3(0.3,0.59,0.11))*(bloom_enabled?0.65:1.0);if(visualize_alpha)rgb=vec3(alpha);ALBEDO="+SkeletalAlbedoPreview.DisplayExpression(space)+";}";
